CREATE DATABASE IF NOT EXISTS sistema_asistencia_ia CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sistema_asistencia_ia;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS reportes;
DROP TABLE IF EXISTS embeddings_faciales;
DROP TABLE IF EXISTS asistencia;
DROP TABLE IF EXISTS estudiantes;
DROP TABLE IF EXISTS usuarios;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,usuario VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,rol VARCHAR(50) DEFAULT 'ADMIN',activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE estudiantes(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,dni VARCHAR(12) UNIQUE,nombres VARCHAR(120) NOT NULL,apellidos VARCHAR(120) NOT NULL,grado VARCHAR(20) NOT NULL,seccion VARCHAR(10) NOT NULL,email VARCHAR(120),telefono VARCHAR(30),foto_url VARCHAR(255),activo BOOLEAN DEFAULT TRUE,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE asistencia(id INT AUTO_INCREMENT PRIMARY KEY,estudiante_id INT NOT NULL,fecha DATE NOT NULL,hora TIME NOT NULL,estado VARCHAR(30) NOT NULL,confianza FLOAT DEFAULT 0,metodo VARCHAR(50) DEFAULT 'FACIAL',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(estudiante_id) REFERENCES estudiantes(id) ON DELETE CASCADE);
CREATE TABLE embeddings_faciales(id INT AUTO_INCREMENT PRIMARY KEY,estudiante_id INT NOT NULL UNIQUE,vector LONGBLOB NULL,vector_json LONGTEXT NULL,modelo VARCHAR(80) DEFAULT 'face_recognition_resnet',precision_estimada FLOAT DEFAULT 0.97,actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(estudiante_id) REFERENCES estudiantes(id) ON DELETE CASCADE);
CREATE TABLE reportes(id INT AUTO_INCREMENT PRIMARY KEY,tipo VARCHAR(50) NOT NULL,descripcion TEXT,ruta_archivo VARCHAR(255),generado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
